var rotate = function(matrix) {
    const n = matrix.length;
    for (let row = 0; row < n; row++) {
        for (let col = row + 1; col < n; col++) {
            const tmp = matrix[row][col];
            matrix[row][col] = matrix[col][row];
            matrix[col][row] = tmp;
        }
    }
    for (const row of matrix) {
        row.reverse();
    }
};

